                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            comps.append(comp)
    panel = max(comps, key=len)
    r0, r1 = min(r for r,c in panel), max(r for r,c in panel)
    c0, c1 = min(c for r,c in panel), max(c for r,c in panel)
    a = [row[c0:c1+1] for row in grid[r0:r1+1]]
    outside = [(r,c,grid[r][c]) for comp in comps if comp is not panel for r,c in comp]
    # Small singleton components are the three external corner labels.
    outside = [(r,c,v) for r,c,v in outside if v not in (0,1)]
    inner = {}
    for r,row in enumerate(a):
        for c,v in enumerate(row):
            if v not in (0,1): inner[v]=(r,c)
    if len(outside) != 3 or len(inner) != 3:
        raise ValueError('expected three inner and outer corner labels')
    er=[r for r,c,v in outside]; ec=[c for r,c,v in outside]
    target={v:(0 if r==min(er) else 1, 0 if c==min(ec) else 1) for r,c,v in outside}
    h,w=len(a),len(a[0])
    transforms = [
        lambda m: [row[:] for row in m],
        lambda m: [row[::-1] for row in m],
        lambda m: [row[:] for row in m[::-1]],
        lambda m: [row[::-1] for row in m[::-1]],
        lambda m: [list(row) for row in zip(*m)],
        lambda m: [list(row) for row in zip(*m[::-1])],
        lambda m: [list(row) for row in zip(*[row[::-1] for row in m])],
        lambda m: [list(row) for row in zip(*m)][::-1],
    ]
    # Match the same label colors to the corresponding inset corners.
    for f in transforms:
        b=f(a); bh,bw=len(b),len(b[0])
        ok=True
        for color, (r,c) in inner.items():
